import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';

const DB_PATH = path.join(process.cwd(), 'database', 'sangsi.db');
const SCHEMA_PATH = path.join(process.cwd(), 'database', 'schema.sql');

// Ensure the database directory exists
const dbDir = path.dirname(DB_PATH);
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true });
}

const db = new Database(DB_PATH);

// Enable WAL mode for better performance
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

// Initialize schema on module load
const schema = fs.readFileSync(SCHEMA_PATH, 'utf-8');
db.exec(schema);

export default db;

import { NextRequest, NextResponse } from 'next/server';
import db from '@/lib/db';
import type { SubmissionInput, SubmissionRow } from '@/lib/types';
import * as XLSX from 'xlsx';

export async function POST(request: NextRequest) {
  let body: SubmissionInput;

  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: '잘못된 요청 형식입니다.' }, { status: 400 });
  }

  const { department_name, dean_name, submitted_at, candidates, hiringProgress } = body;

  if (!department_name || !dean_name || !submitted_at) {
    return NextResponse.json(
      { error: '필수 필드가 누락되었습니다. (department_name, dean_name, submitted_at)' },
      { status: 400 }
    );
  }

  try {
    const insertSubmission = db.prepare(
      `INSERT INTO submissions (department_name, dean_name, submitted_at) VALUES (?, ?, ?)`
    );
    const insertCandidate = db.prepare(
      `INSERT INTO candidates (submission_id, name, birth_year, current_affiliation, current_position, major_field, total_papers, jcr_ratio, fwci, remarks)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    );
    const insertDegree = db.prepare(
      `INSERT INTO candidate_degrees (candidate_id, school, major, degree_year, degree_type)
       VALUES (?, ?, ?, ?, ?)`
    );
    const insertCareer = db.prepare(
      `INSERT INTO candidate_careers (candidate_id, institution, position, period)
       VALUES (?, ?, ?, ?)`
    );
    const insertProgress = db.prepare(
      `INSERT INTO hiring_progress (submission_id, progress_date, content, person_in_charge)
       VALUES (?, ?, ?, ?)`
    );

    const runTransaction = db.transaction(() => {
      const submissionResult = insertSubmission.run(department_name, dean_name, submitted_at);
      const submissionId = submissionResult.lastInsertRowid as number;

      for (const candidate of candidates ?? []) {
        if (!candidate.name) continue;
        const candidateResult = insertCandidate.run(
          submissionId,
          candidate.name,
          candidate.birth_year ?? null,
          candidate.current_affiliation ?? null,
          candidate.current_position ?? null,
          candidate.major_field ?? null,
          candidate.total_papers ?? null,
          candidate.jcr_ratio ?? null,
          candidate.fwci ?? null,
          candidate.remarks ?? null
        );
        const candidateId = candidateResult.lastInsertRowid as number;

        for (const degree of candidate.degrees ?? []) {
          insertDegree.run(
            candidateId,
            degree.school ?? null,
            degree.major ?? null,
            degree.degree_year ?? null,
            degree.degree_type ?? null
          );
        }

        for (const career of candidate.careers ?? []) {
          insertCareer.run(
            candidateId,
            career.institution ?? null,
            career.position ?? null,
            career.period ?? null
          );
        }
      }

      for (const progress of hiringProgress ?? []) {
        insertProgress.run(
          submissionId,
          progress.progress_date ?? null,
          progress.content ?? null,
          progress.person_in_charge ?? null
        );
      }

      return submissionId;
    });

    const id = runTransaction();

    return NextResponse.json({ id, message: '제출 완료' }, { status: 201 });
  } catch (error) {
    console.error('POST /api/submissions error:', error);
    return NextResponse.json(
      { error: '서버 오류가 발생했습니다.', detail: String(error) },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const format = searchParams.get('format');

  try {
    const rows = db
      .prepare(
        `SELECT s.*, COUNT(c.id) as candidate_count
         FROM submissions s
         LEFT JOIN candidates c ON c.submission_id = s.id
         GROUP BY s.id
         ORDER BY s.created_at DESC`
      )
      .all() as SubmissionRow[];

    if (format === 'excel') {
      const candidateRows = db
        .prepare(
          `SELECT c.*, s.department_name, s.dean_name, s.submitted_at
           FROM candidates c
           JOIN submissions s ON s.id = c.submission_id
           ORDER BY s.id, c.id`
        )
        .all();

      const wb = XLSX.utils.book_new();

      const sheet1Data = rows.map((r) => ({
        ID: r.id,
        학과명: r.department_name,
        학장명: r.dean_name,
        제출일시: r.submitted_at,
        상태: r.status,
        후보자수: r.candidate_count ?? 0,
        생성일시: r.created_at,
      }));
      const ws1 = XLSX.utils.json_to_sheet(sheet1Data);
      XLSX.utils.book_append_sheet(wb, ws1, '제출목록');

      const sheet2Data = (candidateRows as Record<string, unknown>[]).map((c) => ({
        ID: c['id'],
        제출ID: c['submission_id'],
        학과명: c['department_name'],
        학장명: c['dean_name'],
        제출일시: c['submitted_at'],
        이름: c['name'],
        출생연도: c['birth_year'],
        현소속: c['current_affiliation'],
        현직위: c['current_position'],
        전공분야: c['major_field'],
        총논문수: c['total_papers'],
        JCR비율: c['jcr_ratio'],
        FWCI: c['fwci'],
        비고: c['remarks'],
      }));
      const ws2 = XLSX.utils.json_to_sheet(sheet2Data);
      XLSX.utils.book_append_sheet(wb, ws2, '후보자목록');

      const buffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

      return new NextResponse(buffer, {
        status: 200,
        headers: {
          'Content-Type':
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': 'attachment; filename="submissions.xlsx"',
        },
      });
    }

    return NextResponse.json(rows);
  } catch (error) {
    console.error('GET /api/submissions error:', error);
    return NextResponse.json(
      { error: '서버 오류가 발생했습니다.', detail: String(error) },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import db from '@/lib/db';
import type { SubmissionDetail, SubmissionRow } from '@/lib/types';

interface Params {
  params: { id: string };
}

export async function GET(_request: NextRequest, { params }: Params) {
  const id = parseInt(params.id, 10);

  if (isNaN(id)) {
    return NextResponse.json({ error: '유효하지 않은 ID입니다.' }, { status: 400 });
  }

  try {
    const submission = db
      .prepare(`SELECT * FROM submissions WHERE id = ?`)
      .get(id) as SubmissionRow | undefined;

    if (!submission) {
      return NextResponse.json({ error: '해당 제출 데이터를 찾을 수 없습니다.' }, { status: 404 });
    }

    type CandidateRow = {
      id: number;
      submission_id: number;
      name: string;
      birth_year?: number;
      current_affiliation?: string;
      current_position?: string;
      major_field?: string;
      total_papers?: number;
      jcr_ratio?: number;
      fwci?: number;
      remarks?: string;
      created_at?: string;
    };

    type DegreeRow = {
      id: number;
      candidate_id: number;
      school?: string;
      major?: string;
      degree_year?: number;
      degree_type?: string;
    };

    type CareerRow = {
      id: number;
      candidate_id: number;
      institution?: string;
      position?: string;
      period?: string;
    };

    type ProgressRow = {
      id: number;
      submission_id: number;
      progress_date?: string;
      content?: string;
      person_in_charge?: string;
    };

    const candidateRows = db
      .prepare(`SELECT * FROM candidates WHERE submission_id = ? ORDER BY id`)
      .all(id) as CandidateRow[];

    const candidates = candidateRows.map((candidate) => {
      const degrees = db
        .prepare(`SELECT * FROM candidate_degrees WHERE candidate_id = ? ORDER BY id`)
        .all(candidate.id) as DegreeRow[];

      const careers = db
        .prepare(`SELECT * FROM candidate_careers WHERE candidate_id = ? ORDER BY id`)
        .all(candidate.id) as CareerRow[];

      return {
        id: candidate.id,
        name: candidate.name,
        birth_year: candidate.birth_year,
        current_affiliation: candidate.current_affiliation,
        current_position: candidate.current_position,
        major_field: candidate.major_field,
        total_papers: candidate.total_papers,
        jcr_ratio: candidate.jcr_ratio,
        fwci: candidate.fwci,
        remarks: candidate.remarks,
        degrees: degrees.map((d) => ({
          school: d.school,
          major: d.major,
          degree_year: d.degree_year,
          degree_type: d.degree_type,
        })),
        careers: careers.map((c) => ({
          institution: c.institution,
          position: c.position,
          period: c.period,
        })),
      };
    });

    const hiringProgress = (
      db
        .prepare(
          `SELECT * FROM hiring_progress WHERE submission_id = ? ORDER BY id`
        )
        .all(id) as ProgressRow[]
    ).map((p) => ({
      progress_date: p.progress_date,
      content: p.content,
      person_in_charge: p.person_in_charge,
    }));

    const detail: SubmissionDetail = {
      ...submission,
      candidates,
      hiringProgress,
    };

    return NextResponse.json(detail);
  } catch (error) {
    console.error(`GET /api/submissions/${id} error:`, error);
    return NextResponse.json(
      { error: '서버 오류가 발생했습니다.', detail: String(error) },
      { status: 500 }
    );
  }
}
